def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort
        valid = [interval for interval in intervals if interval[0] < interval[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for current in valid[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                # Overlapping or touching - merge them
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                # Non-overlapping - add as new interval
                merged.append(current)

        return merged

    # Merge both input lists
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    result = []

    for a_interval in a_merged:
        current_ranges = [a_interval]

        for b_interval in b_merged:
            next_ranges = []

            for current in current_ranges:
                start, end = current
                b_start, b_end = b_interval

                # No overlap
                if end <= b_start or start >= b_end:
                    next_ranges.append(current)
                else:
                    # There is overlap - keep the non-overlapping parts
                    if start < b_start:
                        next_ranges.append([start, b_start])
                    if end > b_end:
                        next_ranges.append([b_end, end])

            current_ranges = next_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    return merge_intervals(result)

